INSERT INTO press (description, image_url, name) VALUES
                                                     ('중앙일보는 "중앙에 두다"를 슬로건으로 삼고 현장의 진실을, 통합의 가치를, 내일의 성장을 중앙에 두겠다는 의지를 담은 국내 대표 종합 일간지입니다.', 'https://newsseug-bucket.s3.ap-northeast-2.amazonaws.com/profile/press/joongang-logo.jpg', '중앙일보'),
                                                     ('대한민국을 대표하는 정론지 동아일보는 디지털 창인 동아닷컴과 함께 공정하고 정확한 뉴스로 독자 여러분과 더 나은 미래를 만들어 나가겠습니다.', 'https://newsseug-bucket.s3.ap-northeast-2.amazonaws.com/profile/press/donga-logo.jpg', '동아일보');
